export function getAssayPaymentErrorMessage(code: AssayPaymentError): string {
  if (process.env['NODE_ENV'] !== 'production') {
    return (assayPaymentErrorMessages as Record<AssayPaymentError, string>)[code];
  }

  return 'Error message not available in production bundles.';
}

export function isAssayPaymentError<TProgramErrorCode extends AssayPaymentError>(
  error: unknown,
  transactionMessage: { instructions: Record<number, { programAddress: Address }> },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    ASSAY_PAYMENT_PROGRAM_ADDRESS,
    code,
  );
}
